<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\DB;

/**
 * `myat_tasks` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $ID
 * @property int|null $ProjectID
 * @property string|null $Title
 * @property string|null $Description
 * @property string|null $Status
 * @property string|null $Priority
 * @property Carbon|null $DueDate
 * @property int|null $Sort
 * @property int|null $TransferID
 * @property string|null $CreatedBy
 * @property Carbon|null $CreatedAt
 * @property Carbon|null $UpdatedAt
 * @property Carbon|null $CompletedAt
 */
class MyatTask extends Model
{
    protected $table = 'myat_tasks';

    protected $primaryKey = 'ID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'ID' => 'integer',
            'ProjectID' => 'integer',
            'DueDate' => 'date',
            'Sort' => 'integer',
            'TransferID' => 'integer',
            'CreatedAt' => 'datetime',
            'UpdatedAt' => 'datetime',
            'CompletedAt' => 'datetime',
        ];
    }

    public function project(): BelongsTo
    {
        return $this->belongsTo(MyatProject::class, 'ProjectID', 'ID');
    }

    public function subtasks(): HasMany
    {
        return $this->hasMany(MyatTaskSubtask::class, 'TaskID', 'ID')->orderBy('Sort')->orderBy('ID');
    }

    public function comments(): HasMany
    {
        return $this->hasMany(MyatTaskComment::class, 'TaskID', 'ID')->orderBy('ID');
    }

    /** The task's files, without their contents. */
    public function files(): HasMany
    {
        return $this->hasMany(MyatTaskFile::class, 'TaskID', 'ID')->select(['ID', 'TaskID', 'Flnm', 'Mime', 'Size', 'Username', 'CreatedAt'])->orderBy('ID');
    }

    /** @return list<string> usernames */
    public function assigneeUsernames(): array
    {
        return DB::table('myat_task_assignees')->where('TaskID', $this->ID)->orderBy('Username')->pluck('Username')->map(fn ($u): string => (string) $u)->all();
    }

    protected static function booted(): void
    {
        static::saving(function (MyatTask $task): void {
            if ($task->isDirty('Status')) {
                $task->CompletedAt = $task->Status === 'done' ? now() : null;
            }
        });
        // A task's pieces go with it.
        static::deleting(function (MyatTask $task): void {
            foreach (['myat_task_assignees', 'myat_task_subtasks', 'myat_task_comments', 'myat_task_files'] as $table) {
                DB::table($table)->where('TaskID', $task->ID)->delete();
            }
        });
    }
}
